SELECT c.CampaignName,c.Objective,c.PrimaryChannel,COUNT(*) Targeted,SUM(i.Delivered) Delivered,SUM(i.Opened) Opened,SUM(i.Clicked) Clicked,SUM(i.Converted) Converted,SUM(i.AttributedRevenueGBP) AttributedRevenueGBP,1.0*SUM(i.Opened)/NULLIF(SUM(i.Delivered),0) OpenRate,1.0*SUM(i.Clicked)/NULLIF(SUM(i.Delivered),0) CTR,1.0*SUM(i.Converted)/NULLIF(SUM(i.Clicked),0) ClickToConversion FROM FactCampaignInteractions i JOIN DimCampaign c ON i.CampaignID=c.CampaignID GROUP BY c.CampaignName,c.Objective,c.PrimaryChannel ORDER BY AttributedRevenueGBP DESC;
